mod support;
use support::deposit_revision;
use graham_ledger::Ledger;
fn csv(account:&str)->String{format!("record_id,type,account_id,date,currency,amount,market,code,kind,name,quantity,price,fee,tax,status,paid_on,net\nd1,deposit,{account},2026-10-01,CNY,1000,,,,,,,,,,,\nb1,buy,{account},2026-10-02,CNY,,CN,600036,stock,招商银行,10,10,0,0,,,\nf1,dividend,{account},2026-10-03,CNY,100,CN,600036,stock,招商银行,,,,10,paid,2026-10-04,90\n")}
#[test]
fn preview_then_confirm_csv_is_atomic_deduplicated_and_keeps_original_provenance(){
 let dir=tempfile::tempdir().unwrap();let path=dir.path().join("ledger.sqlite3");let mut ledger=Ledger::open(&path).unwrap();let a=ledger.create_account("导入验收","CNY").unwrap();let text=csv(&a);
 let before=ledger.snapshot().unwrap();let preview=ledger.preview_csv(&text).unwrap();assert!(preview.can_commit);assert_eq!(preview.new_count,3);assert_eq!(preview.rows[1].record_type,"buy");assert_eq!(preview.rows[2].currency,"CNY");assert_eq!(ledger.snapshot().unwrap().accounts,before.accounts);assert!(ledger.import_log().unwrap().batches.is_empty());
 let result=ledger.commit_csv(&text,&preview.fingerprint).unwrap();assert_eq!(result.snapshot.accounts[0].balance,"990.00");assert_eq!(result.snapshot.positions[0].quantity,"10");assert_eq!(result.snapshot.positions[0].cost,"100.00");assert_eq!(result.snapshot.dividend_totals[0].net,"90.00");assert_eq!(result.log.batches.len(),1);assert_eq!(result.log.batches[0].raw_csv,text);assert_eq!(result.log.items.len(),3);assert!(result.log.items[1].raw.contains("招商银行"));
 let repeated=ledger.preview_csv(&text).unwrap();assert_eq!(repeated.new_count,0);assert_eq!(repeated.duplicate_count,3);assert!(!repeated.can_commit);assert!(ledger.commit_csv(&text,&repeated.fingerprint).is_err());
 let mut changed=text.replace(",1000,",",999,");assert!(!ledger.preview_csv(&changed).unwrap().can_commit);changed=text.replace("2026-10-02","2026-99-99");let errors=ledger.preview_csv(&changed).unwrap();assert!(!errors.can_commit);assert!(errors.rows.iter().any(|r|r.error.is_some()));assert!(ledger.commit_csv(&changed,&errors.fingerprint).is_err());assert_eq!(ledger.snapshot().unwrap().accounts,result.snapshot.accounts);
 drop(ledger);let ledger=Ledger::open(&path).unwrap();assert_eq!(ledger.import_log().unwrap().items.len(),3);assert_eq!(ledger.snapshot().unwrap().accounts[0].balance,"990.00");
}

#[test]
fn imported_records_can_be_corrected_and_batch_undo_refuses_dependencies_without_losing_dedup(){
 use graham_ledger::TradeInput;
 let dir=tempfile::tempdir().unwrap();let mut ledger=Ledger::open(&dir.path().join("ledger.sqlite3")).unwrap();let a=ledger.create_account("纠错账户","CNY").unwrap();let text=csv(&a);let p=ledger.preview_csv(&text).unwrap();let imported=ledger.commit_csv(&text,&p.fingerprint).unwrap();let deposit=&imported.log.items[0];let buy=&imported.log.items[1];let batch=&imported.log.batches[0];
 let correction=format!("record_id,type,account_id,date,currency,amount\nd1,deposit,{a},2026-10-01,CNY,1200\n");
 let corrected=ledger.revise_import_item(&deposit.id,&correction,&imported.log.fingerprint).unwrap();assert_eq!(corrected.snapshot.accounts[0].balance,"1190.00");assert_eq!(corrected.log.items[0].raw,deposit.raw);assert_eq!(corrected.log.items[0].history.len(),2);assert_eq!(corrected.log.batches[0].raw_csv,text);
 assert!(ledger.revise_import_item(&deposit.id,&correction,&imported.log.fingerprint).is_err());let entry=&corrected.snapshot.entries[0];assert!(ledger.revise_deposit(&entry.id, deposit_revision(&ledger, &entry.id),"2026-10-01","5000", "").is_err());assert_eq!(ledger.snapshot().unwrap().accounts[0].balance,"1190.00");
 let deleted=ledger.set_import_item_deleted(&buy.id,&corrected.log.fingerprint,true).unwrap();assert_eq!(deleted.snapshot.accounts[0].balance,"1290.00");let restored=ledger.set_import_item_deleted(&buy.id,&deleted.log.fingerprint,false).unwrap();assert_eq!(restored.snapshot.accounts[0].balance,"1190.00");
 let sell=TradeInput{account_id:a.clone(),occurred_on:"2026-10-10".into(),market:"CN".into(),code:"600036".into(),kind:"stock".into(),name:"招商银行".into(),currency:"CNY".into(),side:"sell".into(),quantity:"10".into(),price:"12".into(),fee:"0".into(),tax:"0".into(),note:"后续依赖".into()};let sold=ledger.record_trade(&sell).unwrap();let preview=ledger.preview_import_batch_undo(&batch.id).unwrap();assert!(!preview.can_undo);assert!(preview.error.is_some());assert_eq!(preview.items.len(),3);assert!(ledger.undo_import_batch(&batch.id,&preview.fingerprint).is_err());assert_eq!(ledger.snapshot().unwrap().accounts,sold.accounts);
 let sell=sold.trades.iter().find(|t|t.source=="手动录入").unwrap();ledger.set_trade_deleted(&sell.id,sell.revision_id,true).unwrap();let preview=ledger.preview_import_batch_undo(&batch.id).unwrap();assert!(preview.can_undo);let undone=ledger.undo_import_batch(&batch.id,&preview.fingerprint).unwrap();assert_eq!(undone.snapshot.accounts[0].balance,"0.00");assert!(undone.log.items.iter().all(|i|i.deleted));assert!(undone.log.batches[0].withdrawn_at.is_some());let repeated=ledger.preview_csv(&text).unwrap();assert_eq!(repeated.duplicate_count,3);assert_eq!(repeated.new_count,0);
 let restored=ledger.set_import_item_deleted(&deposit.id,&undone.log.fingerprint,false).unwrap();assert_eq!(restored.snapshot.accounts[0].balance,"1200.00");assert_eq!(restored.log.items[0].history.len(),4);
 let backup=dir.path().join("imports.grahambak");let password="csv-backup-password";ledger.export_backup(&backup,password).unwrap();let p=Ledger::preview_backup(&backup,password).unwrap();let current=&restored.snapshot.entries[0];ledger.record_deposit(&a,"2026-10-20","10", "").unwrap();let result=ledger.restore_backup(&backup,password,&p.fingerprint,&dir.path().join("recovery")).unwrap();assert_eq!(result.snapshot.accounts[0].balance,"1200.00");assert_eq!(ledger.import_log().unwrap().items[0].history.len(),4);assert_eq!(ledger.import_log().unwrap().batches[0].raw_csv,text);assert!(ledger.set_deposits_deleted(&[graham_ledger::RecordSelection{id:current.id.clone(),revision_id:current.revision_id}],true).is_err());assert_eq!(ledger.preview_csv(&text).unwrap().duplicate_count,3);
 let mixed=format!("record_id,type,account_id,date,currency,amount\nd1,deposit,{a},2026-10-01,CNY,1000\nd2,deposit,{a},2026-10-20,CNY,10\n");let p=ledger.preview_csv(&mixed).unwrap();assert_eq!(p.new_count,1);assert_eq!(p.duplicate_count,1);let mixed=ledger.commit_csv(&mixed,&p.fingerprint).unwrap();assert_eq!(mixed.snapshot.accounts[0].balance,"1210.00");assert_eq!(mixed.log.batches.len(),2);let backup=dir.path().join("mixed.grahambak");ledger.export_backup(&backup,password).unwrap();assert!(Ledger::preview_backup(&backup,password).is_ok());
}

fn csv_row(values:&[(&str,&str)])->String{graham_ledger::CSV_HEADER.split(',').map(|key|{let value=values.iter().find(|(k,_)|*k==key).map(|(_,v)|*v).unwrap_or("");if value.contains([',','"','\n','\r']){format!("\"{}\"",value.replace('"',"\"\""))}else{value.into()}}).collect::<Vec<String>>().join(",")}
fn rewrite_backup(source:&std::path::Path,target:&std::path::Path,password:&str,change:impl FnOnce(&mut serde_json::Value)){
 use age::secrecy::SecretString;let mut identity=age::scrypt::Identity::new(SecretString::from(password.to_owned()));identity.set_max_work_factor(18);let mut doc:serde_json::Value=serde_json::from_slice(&age::decrypt(&identity,&std::fs::read(source).unwrap()).unwrap()).unwrap();change(&mut doc);let mut recipient=age::scrypt::Recipient::new(SecretString::from(password.to_owned()));recipient.set_work_factor(18);std::fs::write(target,age::encrypt(&recipient,&serde_json::to_vec(&doc).unwrap()).unwrap()).unwrap();
}
#[test]
fn all_csv_events_preserve_cash_scope_quoted_rows_and_backup_provenance(){
 let dir=tempfile::tempdir().unwrap();let mut ledger=Ledger::open(&dir.path().join("ledger.sqlite3")).unwrap();let a=ledger.create_account("转出","CNY").unwrap();let b=ledger.create_account("转入","CNY").unwrap();let c=ledger.create_account("美元","USD").unwrap();
 let header=graham_ledger::CSV_HEADER;let note="含,逗号\"与\n换行";
 let rows=[
 csv_row(&[("record_id","d"),("type","deposit"),("account_id",&a),("date","2026-10-01"),("currency","CNY"),("amount","2000"),("note",note)]),
 csv_row(&[("record_id","t"),("type","transfer"),("account_id",&a),("date","2026-10-01"),("currency","CNY"),("amount","200"),("to_account_id",&b),("to_currency","CNY"),("to_amount","200"),("rate","1")]),
 csv_row(&[("record_id","w"),("type","withdrawal"),("account_id",&a),("date","2026-10-02"),("currency","CNY"),("amount","100")]),
 csv_row(&[("record_id","x"),("type","exchange"),("account_id",&a),("date","2026-10-02"),("currency","CNY"),("amount","720"),("to_account_id",&c),("to_currency","USD"),("to_amount","100"),("rate","0.13888889")]),
 csv_row(&[("record_id","b"),("type","buy"),("account_id",&b),("date","2026-10-03"),("currency","CNY"),("market","CN"),("code","600036"),("kind","stock"),("name","招商银行"),("quantity","10"),("price","10")]),
 csv_row(&[("record_id","s"),("type","sell"),("account_id",&b),("date","2026-10-04"),("currency","CNY"),("market","CN"),("code","600036"),("kind","stock"),("name","招商银行"),("quantity","5"),("price","12")]),
 csv_row(&[("record_id","o"),("type","opening"),("account_id",&b),("date","2026-09-30"),("currency","CNY"),("amount","50"),("positions","[]")]),
 csv_row(&[("record_id","f"),("type","dividend"),("account_id",&c),("date","2026-10-05"),("currency","USD"),("market","US"),("code","AAPL"),("kind","stock"),("name","苹果"),("amount","10"),("tax","1"),("net","9"),("status","pending")])];
 let text=format!("\u{feff}{header}\r\n{}\r\n",rows.join("\r\n"));let p=ledger.preview_csv(&text).unwrap();assert!(p.can_commit,"{:?}",p.error);assert_eq!(p.rows[1].line,4);let result=ledger.commit_csv(&text,&p.fingerprint).unwrap();assert_eq!(result.snapshot.accounts[0].balance,"980.00");assert_eq!(result.snapshot.accounts[1].balance,"210.00");assert_eq!(result.snapshot.accounts[2].balance,"100.00");assert_eq!(result.snapshot.entries[0].note,note);assert_eq!(result.snapshot.positions[0].cost,"50.00");assert_eq!(result.snapshot.positions[0].realized,"10.00");assert_eq!(result.snapshot.dividend_totals[0].pending,"9.00");
 let flows=ledger.cash_flows(&[a.clone(),b,c],"2026-10-01","2026-10-31").unwrap();assert!(flows.unavailable_reason.is_none());assert_eq!(flows.internal_count,2);let cny=flows.totals.iter().find(|t|t.currency=="CNY").unwrap();assert_eq!(cny.net_capital,"1900.00");assert_eq!(cny.outflow,"100.00");assert_eq!(ledger.snapshot_on("2026-10-02").unwrap().accounts[0].balance.as_deref(),Some("980.00"));
 let equivalent=text.replace(",2000,",",2000.00,");let repeated=ledger.preview_csv(&equivalent).unwrap();assert_eq!(repeated.duplicate_count,8);assert_eq!(repeated.new_count,0);
 let unknown=text.replace(",withdrawal,",",mystery,");let bad=ledger.preview_csv(&unknown).unwrap();assert!(!bad.can_commit);assert!(bad.rows.iter().any(|r|r.error.as_deref().is_some_and(|e|e.contains("未知"))));assert!(ledger.preview_csv("record_id,type,account_id,date,currency\nx,deposit,\"unfinished").is_err());
 let opening=result.snapshot.openings.first().unwrap();let item=result.log.items.iter().find(|i|i.record_type=="opening").unwrap();let deleted=ledger.set_import_item_deleted(&item.id,&result.log.fingerprint,true).unwrap();assert!(ledger.permanently_delete_opening(&opening.id,deleted.snapshot.openings[0].revision_id).is_err());let restored=ledger.set_import_item_deleted(&item.id,&deleted.log.fingerprint,false).unwrap();assert_eq!(restored.snapshot.accounts,result.snapshot.accounts);
 let backup=dir.path().join("full.grahambak");let password="full-csv-backup-password";ledger.export_backup(&backup,password).unwrap();let preview=Ledger::preview_backup(&backup,password).unwrap();assert_eq!(preview.record_count,8);
 let tampered=dir.path().join("tampered.grahambak");rewrite_backup(&backup,&tampered,password,|doc|doc["imports"]["items"][0]["raw"]=serde_json::json!("tampered"));assert!(Ledger::preview_backup(&tampered,password).is_err());
 let missing=dir.path().join("missing.grahambak");rewrite_backup(&backup,&missing,password,|doc|{doc.as_object_mut().unwrap().remove("imports");});assert!(Ledger::preview_backup(&missing,password).is_err());
 let stale=format!("record_id,type,account_id,date,currency,amount\nnew,deposit,{a},2026-10-20,CNY,1\n");let p=ledger.preview_csv(&stale).unwrap();ledger.record_deposit(&a,"2026-10-20","1", "").unwrap();assert!(ledger.commit_csv(&stale,&p.fingerprint).is_err());let recovered=ledger.restore_backup(&backup,password,&preview.fingerprint,&dir.path().join("recovery")).unwrap();assert_eq!(recovered.snapshot.accounts,result.snapshot.accounts);assert_eq!(ledger.import_log().unwrap().items.len(),8);assert_eq!(ledger.preview_csv(&text).unwrap().duplicate_count,8);
}

#[test]
fn duplicate_opening_with_wrong_currency_blocks_the_entire_csv(){
 let dir=tempfile::tempdir().unwrap();let mut ledger=Ledger::open(&dir.path().join("ledger.sqlite3")).unwrap();let a=ledger.create_account("期初原币","CNY").unwrap();let text=format!("record_id,type,account_id,date,currency,amount\no,opening,{a},2026-09-30,CNY,100\n");let p=ledger.preview_csv(&text).unwrap();ledger.commit_csv(&text,&p.fingerprint).unwrap();
 let invalid=format!("record_id,type,account_id,date,currency,amount\no,opening,{a},2026-09-30,USD,100\nd,deposit,{a},2026-10-01,CNY,1\n");let p=ledger.preview_csv(&invalid).unwrap();assert!(!p.can_commit);assert!(p.rows[0].error.as_deref().is_some_and(|e|e.contains("币种")));assert!(ledger.commit_csv(&invalid,&p.fingerprint).is_err());assert_eq!(ledger.snapshot().unwrap().accounts[0].balance,"100.00");
}
#[test]
fn encrypted_backup_missing_a_withdrawal_refuses_to_inflate_cash_or_lose_dedup(){
 let dir=tempfile::tempdir().unwrap();let mut ledger=Ledger::open(&dir.path().join("ledger.sqlite3")).unwrap();let a=ledger.create_account("完整来源","CNY").unwrap();let text=format!("record_id,type,account_id,date,currency,amount\nd,deposit,{a},2026-10-01,CNY,1000\nw,withdrawal,{a},2026-10-02,CNY,100\n");let p=ledger.preview_csv(&text).unwrap();let result=ledger.commit_csv(&text,&p.fingerprint).unwrap();assert_eq!(result.snapshot.accounts[0].balance,"900.00");
 let backup=dir.path().join("source.grahambak");let invalid=dir.path().join("missing-withdrawal.grahambak");let password="missing-withdrawal-password";ledger.export_backup(&backup,password).unwrap();rewrite_backup(&backup,&invalid,password,|doc|doc["imports"]["items"].as_array_mut().unwrap().retain(|i|i["recordType"]!="withdrawal"));
 assert!(Ledger::preview_backup(&invalid,password).is_err());assert!(ledger.restore_backup(&invalid,password,"invalid",&dir.path().join("rejected")).is_err());assert_eq!(ledger.snapshot().unwrap().accounts,result.snapshot.accounts);assert_eq!(ledger.preview_csv(&text).unwrap().duplicate_count,2);
}
